/// An element the model names but does not read: it stays in the tree, and the report says
/// so. Its name is all the model holds, so it cannot be made anew from here, only kept or
/// removed.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct Retained {
    /// Its namespace, as the file resolves it.
    pub uri: Option<String>,
    /// Its local name.
    pub local: String,
}

/// A value of a union of an enumeration and any string, such as `cs:ST_ColorStyleMethod`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Open<T> {
    /// One of the enumeration's.
    Known(T),
    /// Any other, as written.
    Other(String),
}

impl<T: Lexical> Lexical for Open<T> {
    fn parse_lexical(s: &str) -> Option<Self> {
        Some(match T::parse_lexical(s) {
            Some(value) => Self::Known(value),
            None => Self::Other(s.to_owned()),
        })
    }
    fn to_lexical(&self) -> String {
        match self {
            Self::Known(value) => value.to_lexical(),
            Self::Other(text) => text.clone(),
        }
    }
}

/// A space-separated list of [`Open`] values, such as `cs:ST_StyleEntryModifierList`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct OpenList<T>(pub Vec<Open<T>>);

impl<T: Lexical> Lexical for OpenList<T> {
    fn parse_lexical(s: &str) -> Option<Self> {
        let items = trim_xml(s).split([' ', '\t', '\r', '\n']);
        Some(Self(
            items
                .filter(|item| !item.is_empty())
                .filter_map(Open::parse_lexical)
                .collect(),
        ))
    }
    fn to_lexical(&self) -> String {
        let items: Vec<String> = self.0.iter().map(Lexical::to_lexical).collect();
        items.join(" ")
    }
}

/// `c:axId` or `c:crossAx`, a `c:CT_UnsignedInt` by the schema. Mac PowerPoint writes these
/// negative, so the value is signed here (`T1J-04`). Negative is reported, and kept.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct AxisId {
    /// `val`.
    pub val: Option<i64>,
}

/// `mc:AlternateContent` holding `c14:style`, with `c:style` as its fallback, as PowerPoint
/// writes it under `c:chartSpace`.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct AlternateStyle {
    /// `mc:Choice/@Requires`.
    pub requires: Option<String>,
    /// `c14:style`.
    pub choice: Option<Box<c14::Style>>,
    /// `c:style`.
    pub fallback: Option<Box<c::Style>>,
}

/// `mc:AlternateContent` holding `cdr14:contentPart`, in a chart drawing's anchor.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct AlternateContentPart {
    /// `mc:Choice/@Requires`.
    pub requires: Option<String>,
    /// `cdr14:contentPart`.
    pub choice: Option<Box<cdr14::ContentPart>>,
    /// What `mc:Fallback` holds, kept in the tree.
    pub fallback: Vec<Retained>,
}

/// One chart-family part, by its root.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ChartPart {
    /// `c:chartSpace`.
    Chart(Box<c::ChartSpace>),
    /// `cx:chartSpace`.
    ChartEx(Box<cx::ChartSpace>),
    /// `c:userShapes`.
    UserShapes(Box<cdr::Drawing>),
    /// `cs:chartStyle`.
    Style(Box<cs::ChartStyle>),
    /// `cs:colorStyle`.
    Colors(Box<cs::ColorStyle>),
}

/// What `p:graphicFrame` holds when it holds a chart.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ChartReference {
    /// Whether it is `cx:chart`, a 2016+ chart, rather than `c:chart`.
    pub extended: bool,
    /// `r:id`, the relationship to the chart part.
    pub rel_id: Option<String>,
}

impl c::ChartSpace {
    /// The families in this chart's plot area, in the order they draw.
    pub fn charts(&self) -> &[c::PlotAreaCharts] {
        self.chart
            .as_ref()
            .and_then(|c| c.plot_area.as_ref())
            .map_or(&[], |p| &p.charts)
    }
}

impl c::PlotAreaCharts {
    /// The axis ids this family names. A pie has none.
    pub fn axis_ids(&self) -> &[AxisId] {
        match self {
            Self::AreaChart(x) => &x.ax_id,
            Self::Area3DChart(x) => &x.ax_id,
            Self::LineChart(x) => &x.ax_id,
            Self::Line3DChart(x) => &x.ax_id,
            Self::StockChart(x) => &x.ax_id,
            Self::RadarChart(x) => &x.ax_id,
            Self::ScatterChart(x) => &x.ax_id,
            Self::BarChart(x) => &x.ax_id,
            Self::Bar3DChart(x) => &x.ax_id,
            Self::SurfaceChart(x) => &x.ax_id,
            Self::Surface3DChart(x) => &x.ax_id,
            Self::BubbleChart(x) => &x.ax_id,
            Self::PieChart(_)
            | Self::Pie3DChart(_)
            | Self::DoughnutChart(_)
            | Self::OfPieChart(_) => &[],
        }
    }
}

impl c::PlotAreaAxes {
    /// `axId` and `crossAx`.
    pub fn ids(&self) -> (Option<&AxisId>, Option<&AxisId>) {
        match self {
            Self::ValAx(x) => (x.ax_id.as_ref(), x.cross_ax.as_ref()),
            Self::CatAx(x) => (x.ax_id.as_ref(), x.cross_ax.as_ref()),
            Self::DateAx(x) => (x.ax_id.as_ref(), x.cross_ax.as_ref()),
            Self::SerAx(x) => (x.ax_id.as_ref(), x.cross_ax.as_ref()),
        }
    }
}
